import { WalletAccount } from '@wallet-standard/base'
import { create, StateCreator } from 'zustand'
import { persist } from 'zustand/middleware'

interface AccountState {
  accounts: WalletAccount[]
  addressChangeVersion: number
  currentAccount: WalletAccount | undefined
  saveCurrentAccount: (account: WalletAccount | undefined) => void
  saveAccounts: (accounts: WalletAccount[]) => void
  isOpenWalletModal: boolean
  onWalletModal: (isOpen: boolean) => void
  accountServiceNameObj: any
  setAccountServiceNameObj: (value: any) => void
}

// const useAccountStore = create<AccountState>((set, get) => ({
const store: StateCreator<AccountState> = (set, get) => ({
  addressChangeVersion: 0,
  accounts: [],
  currentAccount: undefined,
  isOpenWalletModal: false,
  saveCurrentAccount: (account: WalletAccount | undefined) => {
    const lastAddress = get().currentAccount?.address
    const addressChangeVersion = get().addressChangeVersion
    // 当且仅当  切换地址 才生效
    if (lastAddress && account && lastAddress !== account.address) {
      set({
        currentAccount: account,
        addressChangeVersion: addressChangeVersion + 1
      })
    } else {
      set({
        currentAccount: account
      })
    }
  },
  saveAccounts: (accounts: WalletAccount[]) => {
    set({
      accounts
    })
  },
  onWalletModal: (isOpen: boolean) => {
    set({
      isOpenWalletModal: isOpen
    })
  },
  accountServiceNameObj: {},
  setAccountServiceNameObj: (value: any) => {
    const originValue = get().accountServiceNameObj
    set({
      accountServiceNameObj: { ...originValue, ...value }
    })
  }
})

// export { useAccountStore }
const useAccountStore = create(
  persist(store, {
    name: 'useAccountStore',
    partialize: state => {
      const { accountServiceNameObj } = state
      return { accountServiceNameObj }
    },
    version: 3
  })
)
export { useAccountStore }
