import { Token } from '@cetus/types/src/common-types'
import { AllTokensTable, VariousTokensTable, VERIFIED_TOKEN_MAP_KEY } from '@cetus/utils'
import { extractStructTagFromType } from '@cetusprotocol/common-sdk'
import { create, StateCreator } from 'zustand'

interface TokenState {
  verifiedTokenMap: Map<string, Token>
  setVerifiedTokenMap: (data: Map<string, Token>) => void
  setAllTokenMap: (data: Map<string, Token>) => void
  addToken: (info: Token) => void
  deleteToken: (coinType: string) => void
  addTokenList: (info: Token[]) => void
  deleteTokenList: (coinTypeList: string[]) => void
  clearTokenMap: () => void
}

const store: StateCreator<TokenState> = (set, get) => {
  return {
    verifiedTokenMap: new Map<string, Token>(),
    setVerifiedTokenMap: (data: Map<string, any>) => {
      console.log(data, 'setVerifiedTokenMapsetVerifiedTokenMap')
      set(() => ({
        verifiedTokenMap: data
      }))
      VariousTokensTable.setItem(VERIFIED_TOKEN_MAP_KEY, data)
    },
    setAllTokenMap: (data: Map<string, any>) => {
      data.forEach((t, k) => {
        AllTokensTable.setItem(k, t)
      })
    },
    addToken: (token: Token) => {
      AllTokensTable.setItem(extractStructTagFromType(token.coin_type).full_address, token)
    },
    deleteToken: (coinType: string) => {
      AllTokensTable.removeItem(coinType)
    },
    addTokenList: (tokens: Token[]) => {
      tokens.forEach(token => {
        AllTokensTable.setItem(extractStructTagFromType(token.coin_type).full_address, token)
      })
    },
    deleteTokenList(coinTypeList: string[]) {
      coinTypeList.forEach(type => {
        AllTokensTable.removeItem(type)
      })
    },
    clearTokenMap: () => {
      AllTokensTable.clear()
    }
  }
}

// const useTokenStore = create(persist(store, { name: 'useTokenStore', version: 2 }))
// export default useTokenStore

const useTokenStore = create(store)
export default useTokenStore

// 从 localForage 加载数据

VariousTokensTable.getItem<any>(VERIFIED_TOKEN_MAP_KEY).then(savedTokenMap => {
  console.log('🚀 ~ file: token.ts:63 ~ savedTokenMap:', savedTokenMap)
  if (savedTokenMap !== null) {
    useTokenStore.getState().setVerifiedTokenMap(savedTokenMap)
  }
})
AllTokensTable.getAllItems<Token>().then(savedTokenMap => {
  console.log('🚀 ~ file: token.ts:69 ~ savedTokenMap:', savedTokenMap)
  if (savedTokenMap !== null) {
    useTokenStore.getState().setAllTokenMap(savedTokenMap)
  }
})

