import { LocalForageService } from './local-forage-service'

// 单例模式实现
class AllTokensTableImpl extends LocalForageService {
  private static instance: AllTokensTableImpl

  private constructor() {
    super('CetusSite', 'allTokens')
  }

  public static getInstance(): AllTokensTableImpl {
    if (!AllTokensTableImpl.instance) {
      AllTokensTableImpl.instance = new AllTokensTableImpl()
    }
    return AllTokensTableImpl.instance
  }
}

// 为了保持向后兼容，保留静态方法接口
export class AllTokensTable {
  private static table = AllTokensTableImpl.getInstance()

  static async setItem<T>(key: string, value: T): Promise<void> {
    return AllTokensTable.table.setItem(key, value)
  }

  static async getItem<T>(key: string): Promise<T | null> {
    return AllTokensTable.table.getItem(key)
  }

  static async getAllItems<T>(): Promise<Map<string, T> | null> {
    return AllTokensTable.table.getAllItems()
  }

  static async removeItem(key: string): Promise<void> {
    return AllTokensTable.table.removeItem(key)
  }

  static async clear(): Promise<void> {
    return AllTokensTable.table.clear()
  }
}
