import { useAccountStore } from '@cetus/stores'
import { Token } from '@cetus/types'
import { Icon, NumericFormatInput, SingleCoinImage } from '@cetus/ui-kit'
import { convertScientificToDecimal, d, formatCurrencyWithKMB, formatNumberWithDown, textEllipses } from '@cetus/utils'
import { CoinAssist } from '@cetusprotocol/common-sdk'
import { Box, BoxProps, Button, HStack, InputGroup, InputRightAddon, Skeleton, Text, VStack } from '@chakra-ui/react'
import { forwardRef, lazy, Suspense, useImperativeHandle, useRef, useState } from 'react'
import LockInput, { LockType } from './LockInput'
import SelectTab, { SelectTabProps } from './SelectTab'
const CoinSelect = lazy(() => import('./CoinSelect'))

export interface TradeInputProps {
  title?: string
  value: string
  amountValue?: string
  onChange: (value: string, isClickMax?: boolean, isHalfClickMax?: boolean) => void
  onFocusChange?: (focus: boolean) => void
  placeholder: string
  balance: string | number
  selectable?: boolean
  onTokenChange?: (token: any) => void
  token?: Token
  half?: boolean
  max?: boolean
  loading?: boolean
  inputAllowed?: boolean
  hideSelf?: boolean
  wrapStyle?: BoxProps
  needRemainBalance?: boolean
  balanceLabel?: string
  calculateAvailableLoading?: boolean
  currentCoinKey?: string
  whiteTokenList?: Token[]
  isWidget?: boolean
  isDcaTo?: boolean
  inputTabOptions?: SelectTabProps
  openSelectTokenModal?: () => void
  lock?: LockType
}

const TradeInput = forwardRef(function Index(
  {
    title,
    value,
    amountValue,
    onFocusChange,
    onChange,
    placeholder = '0.0',
    balance,
    selectable,
    onTokenChange,
    token,
    half = true,
    max = true,
    lock,
    loading,
    inputAllowed = true,
    hideSelf = false,
    needRemainBalance = true,
    balanceLabel,
    wrapStyle = {},
    calculateAvailableLoading = false,
    currentCoinKey,
    whiteTokenList,
    isWidget = false,
    isDcaTo = false,
    inputTabOptions,
    openSelectTokenModal
  }: TradeInputProps,
  ref
) {
  const {
    type = 'borderTab',
    tabList = [],
    currentTab = '',
    handleChangeTab = () => {},
    wrapStyle: TabWrapStyle = { h: '60px', p: '8px' },
    itemStyle = { fontSize: '14px' }
  } = inputTabOptions || {}

  const fromRef = useRef<HTMLInputElement | null>(null)
  const [focused, setFocused] = useState<boolean>(false)
  const { currentAccount } = useAccountStore()

  const handleHalfBalance = () => {
    const _half = d(balance || 0).div(2)
    if (value && _half.eq(value)) {
      return
    }
    onChange?.(formatNumberWithDown(_half.toString(), token?.decimals, true, true).toString(), false, true)
  }

  const handleMaxBalance = () => {
    const _max = d(balance || 0)
    const isSuiCoin = CoinAssist.isSuiCoin(token?.coin_type || '')
    const remainAmount = isSuiCoin && needRemainBalance ? 0.05 : 0
    let useAmount = _max
    if (isSuiCoin && d(_max).gt(remainAmount)) {
      useAmount = useAmount.sub(remainAmount)
    }
    if (value && d(useAmount).eq(value)) {
      return
    }
    if (d(useAmount).gte(0)) {
      onChange?.(useAmount.toString() || '0', true, false)
    }
  }

  useImperativeHandle(ref, () => {
    return {
      focused
    }
  }, [focused])

  if (hideSelf) {
    return <></>
  }

  return (
    <Box
      ref={fromRef}
      w="100%"
      onFocus={() => {
        setFocused(true)
      }}
      onBlur={() => {
        setFocused(false)
      }}
      borderRadius="16px"
      p={{ base: '16px 8px', lg: '16px' }}
      h="122px"
      border="1px solid"
      backgroundColor={inputAllowed ? 'bg_secondary' : 'card_bg'}
      {...wrapStyle}
      borderColor={focused ? 'token_active_border' : wrapStyle?.borderColor ? wrapStyle?.borderColor : 'border'}
      boxShadow={focused ? '0px 0px 6px 0px #0067AD' : ''}
      pos="relative"
    >
      <HStack w="100%" justify="space-between">
        {title && (
          <Text color="text_paragraph" fontSize="13px" fontWeight="500" h="16px" mb={isDcaTo ? '0px' : '4px'} textAlign="left">
            {title}
          </Text>
        )}
        <HStack mt="-16px" mr={{ base: '0', lg: '-8px' }}>
          {inputTabOptions && tabList && tabList?.length > 0 && (
            <SelectTab
              type={type}
              tabList={tabList}
              currentTab={currentTab}
              handleChangeTab={tab => handleChangeTab(tab)}
              wrapStyle={TabWrapStyle}
              itemStyle={itemStyle}
            />
          )}
        </HStack>
      </HStack>

      <VStack gap={isDcaTo ? '0px' : '8px'} flexDirection={isDcaTo ? 'column-reverse' : 'column'}>
        {/* mb={isWidget ? '0px' : '8px'} */}
        <InputGroup h="38px" fontFamily="Inter" justifyContent={isDcaTo ? 'center' : 'space-between'} gap="12px">
          {!isDcaTo && (
            <Skeleton isLoaded={!loading} height="38px" width="calc(100% - 8px)" borderRadius="8px">
              <NumericFormatInput
                value={convertScientificToDecimal(value, 9)}
                onChange={(value: string) => {
                  onChange?.(value, d(value).eq(balance || '0'))
                }}
                decimals={token?.decimals}
                placeholder={placeholder}
                inputAllowed={inputAllowed}
                onFocus={() => {
                  if (onFocusChange) {
                    onFocusChange(true)
                  }
                }}
                onBlur={() => {
                  if (onFocusChange) {
                    onFocusChange(false)
                  }
                }}
                style={{
                  width: 'calc(100% - 8px)',
                  background: 'none',
                  whiteSpace: 'nowrap',
                  opacity: 1,
                  outline: 'none',
                  color: 'var(--chakra-colors-text_caption)',
                  fontSize: isWidget ? '24px' : '28px',
                  height: '38px',
                  lineHeight: '38px',
                  touchAction: 'manipulation',
                  transition: 'all 0.3s',
                  fontWeight: '500'
                }}
              />
            </Skeleton>
          )}

          <InputRightAddon w={isDcaTo ? '100%' : 'unset'}>
            {selectable ? (
              <Suspense fallback={<Skeleton h="20px" w="100px" borderRadius="8px" />}>
                <CoinSelect
                  openSelectTokenModal={openSelectTokenModal}
                  selectModalCallback={isOpen => {
                    if (isOpen) {
                      setFocused(true)
                    } else {
                      setFocused(false)
                    }
                  }}
                  currentCoinKey={currentCoinKey}
                  whiteTokenList={whiteTokenList}
                  value={token}
                  onSelect={onTokenChange!}
                />
              </Suspense>
            ) : (
              <HStack>
                <SingleCoinImage key={token?.symbol + 'Icon'} imageUrl={token?.logo_url} w="28px" h="28px" coinType={token?.coin_type} />
                <Text color="text_caption" fontSize="16px" fontWeight="600">
                  {textEllipses(token?.symbol || '', 10)}
                </Text>
              </HStack>
            )}
          </InputRightAddon>
        </InputGroup>

        <HStack justify="space-between" w="100%" mt={isDcaTo && currentAccount ? '-20px' : 0}>
          <Text width="50%" flex="0" fontWeight="500">
            {amountValue && !!+amountValue ? `${formatCurrencyWithKMB(amountValue, 2)}` : null}
          </Text>

          {!!currentAccount && (
            <HStack justify="flex-end" gap="8px">
              <Skeleton isLoaded={!calculateAvailableLoading}>
                <HStack gap="4px">
                  {balanceLabel ? <Text>{balanceLabel}</Text> : <Icon xlinkHref="#icon-icon_wallet" svgHover="text_paragraph" cursor="default" />}
                  <Text>{!balance || balance === '0' ? '0.0' : formatNumberWithDown(balance)}</Text>
                </HStack>
              </Skeleton>
              {half && (
                <Button
                  onClick={handleHalfBalance}
                  fontSize="12px"
                  fontWeight="500"
                  lineHeight="20px"
                  color="text_paragraph"
                  w="42px"
                  h="20px"
                  bg={isWidget ? 'swap_bg_secondary' : 'button_outline_bg'}
                  borderRadius="4px"
                  variant="outline"
                >
                  HALF
                </Button>
              )}
              {max && (
                <Button
                  onClick={handleMaxBalance}
                  fontSize="12px"
                  fontWeight="500"
                  lineHeight="20px"
                  color="text_paragraph"
                  w="42px"
                  h="20px"
                  bg={isWidget ? 'swap_bg_secondary' : 'button_outline_bg'}
                  borderRadius="4px"
                  variant="outline"
                >
                  MAX
                </Button>
              )}
            </HStack>
          )}
        </HStack>
      </VStack>
      {((typeof lock === 'boolean' && lock) || (typeof lock === 'object' && lock?.isLock)) && (
        <LockInput
          position="absolute"
          top="-1px"
          borderRadius="16px"
          h={wrapStyle?.h || '108px'}
          left="-1px"
          w="calc(100% + 2px)"
          text={typeof lock === 'object' ? lock?.text : undefined}
          {...(typeof lock === 'object' ? lock?.style || {} : {})}
        />
      )}
    </Box>
  )
})

export default TradeInput
